    attribute brightness : Real := 0.0;
    attribute phaseMs : Integer := 0;
    perform action tick {
      first start;
      then if io_1_valid {
        first start;
        then assign mode := io_1;
      }
      then assign phaseMs := phaseMs + io_2;
      then if mode == 1 {
        first start;
        then assign brightness := (if phaseMs < 1000 ? phaseMs * 1.0 / 1000.0 * 255.0 else (if phaseMs < 2000 ? (2000 - phaseMs) * 1.0 / 1000.0 * 255.0 else (if phaseMs < 3000 ? (phaseMs - 2000) * 1.0 / 1000.0 * 255.0 else (if phaseMs < 4000 ? (4000 - phaseMs) * 1.0 / 1000.0 * 255.0 else (if phaseMs < 5000 ? (phaseMs - 4000) * 1.0 / 1000.0 * 255.0 else (if phaseMs < 6000 ? (6000 - phaseMs) * 1.0 / 1000.0 * 255.0 else 0.0))))));
      } else {
        first start;
        then assign brightness := 255.0;
      }
      then if mode == 2 and brightness != 255.0 {
        first start;
        then assign brightness := 255.0;
      }
    }
    out attribute io_0 : Real = brightness;
    out attribute serial_0_trigger : Boolean = true;
    out attribute serial_0_value_0 : Integer = mode;
  }
